const fmt = (d) => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
};

const hoy = new Date();

const valida = new Date(hoy);
valida.setDate(hoy.getDate() + 2);
if (valida.getDay() === 0) {
    valida.setDate(valida.getDate() + 1);
}

const domingo = new Date(hoy);
const diasHastaDomingo = (7 - hoy.getDay()) % 7 || 7;
domingo.setDate(hoy.getDate() + diasHastaDomingo);

const pasada = new Date(hoy);
pasada.setDate(hoy.getDate() - 1);

pm.collectionVariables.set("fechaValida", fmt(valida));
pm.collectionVariables.set("fechaDomingo", fmt(domingo));
pm.collectionVariables.set("fechaPasada", fmt(pasada));

